CREATE TABLE public.explore_post_reactions (
    post_id UUID NOT NULL REFERENCES public.explore_posts(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
    emoji TEXT NOT NULL REFERENCES internal.explore_emoji_catalog(emoji),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY(post_id, user_id, emoji),
    CHECK(emoji <> '❤️')
);
CREATE INDEX explore_post_reactions_groups ON public.explore_post_reactions(post_id, emoji, created_at DESC);
CREATE INDEX explore_post_reactions_user ON public.explore_post_reactions(user_id);
ALTER TABLE public.explore_post_reactions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.explore_post_reactions FROM PUBLIC, anon, authenticated, service_role;
-- All writes go through the guarded mutation RPC; deletes also cascade on account/post removal.
GRANT SELECT ON public.explore_post_reactions TO service_role;
ALTER TABLE public.user_push_devices ADD COLUMN supports_post_reactions BOOLEAN NOT NULL DEFAULT FALSE;

CREATE FUNCTION internal.explore_reaction_post(self_id UUID, target_kind TEXT, target_id UUID)
RETURNS UUID LANGUAGE plpgsql STABLE SET search_path = '' AS $$
DECLARE resolved_post_id UUID;
BEGIN
    IF target_kind = 'post' THEN
        resolved_post_id := target_id;
    ELSIF target_kind = 'comment' THEN
        SELECT c.post_id INTO resolved_post_id
        FROM public.explore_post_comments c
        JOIN public.users u ON u.id = c.user_id AND NOT u.is_shadowbanned
        LEFT JOIN public.explore_post_comments parent ON parent.id = c.parent_comment_id
        WHERE c.id = target_id AND c.deleted_at IS NULL AND c.moderated_at IS NULL
          AND (c.parent_comment_id IS NULL OR (parent.deleted_at IS NULL AND parent.moderated_at IS NULL
               AND parent.id IS NOT NULL AND parent.parent_comment_id IS NULL
               AND EXISTS (SELECT 1 FROM public.users pu WHERE pu.id=parent.user_id AND NOT pu.is_shadowbanned)))
          AND NOT EXISTS (SELECT 1 FROM public.user_blocks b
              WHERE (b.blocker_id = self_id AND b.blocked_id IN (c.user_id, parent.user_id))
                 OR (b.blocked_id = self_id AND b.blocker_id IN (c.user_id, parent.user_id)));
    ELSE
        RAISE EXCEPTION 'Invalid reaction target' USING ERRCODE = '22023';
    END IF;
    IF resolved_post_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.explore_projected_post_cards(self_id) p WHERE p.post_id = resolved_post_id
    ) OR NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = self_id AND NOT u.is_shadowbanned) THEN
        RAISE EXCEPTION 'Reaction target is unavailable' USING ERRCODE = '42501';
    END IF;
    RETURN resolved_post_id;
END;
$$;

CREATE FUNCTION internal.explore_reaction_page(self_id UUID, target_kind TEXT, target_id UUID,
    after_ordinal INTEGER DEFAULT -1, page_size INTEGER DEFAULT 12)
RETURNS JSONB LANGUAGE sql STABLE SET search_path = '' AS $$
    WITH source AS (
        SELECT r.emoji, r.user_id FROM public.explore_post_reactions r
        WHERE target_kind = 'post' AND r.post_id = target_id
        UNION ALL
        SELECT r.emoji, r.user_id FROM public.explore_comment_reactions r
        WHERE target_kind = 'comment' AND r.comment_id = target_id
    ), groups AS (
        SELECT e.emoji, e.ordinal, count(DISTINCT r.user_id)::INTEGER AS count,
            bool_or(r.user_id = self_id) AS viewer_has_reacted
        FROM source r JOIN internal.explore_emoji_catalog e ON r.emoji = ANY(e.aliases)
        JOIN public.users u ON u.id = r.user_id AND NOT u.is_shadowbanned
        WHERE e.ordinal > after_ordinal AND NOT EXISTS (
            SELECT 1 FROM public.user_blocks b WHERE
                (b.blocker_id = self_id AND b.blocked_id = r.user_id) OR
                (b.blocked_id = self_id AND b.blocker_id = r.user_id))
        GROUP BY e.emoji, e.ordinal ORDER BY e.ordinal
        LIMIT LEAST(GREATEST(page_size, 1), 32) + 1
    ), page AS (
        SELECT * FROM groups ORDER BY ordinal LIMIT LEAST(GREATEST(page_size, 1), 32)
    )
    SELECT jsonb_build_object('reactions', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'emoji', emoji, 'count', count, 'viewer_has_reacted', viewer_has_reacted, 'order', ordinal)
        ORDER BY ordinal) FROM page), '[]'::JSONB), 'reactions_next_cursor',
        CASE WHEN (SELECT count(*) FROM groups) > LEAST(GREATEST(page_size, 1), 32)
            THEN (SELECT max(ordinal) FROM page) ELSE NULL END);
$$;

CREATE FUNCTION public.get_explore_reactions(self_id UUID, target_kind TEXT, target_id UUID,
    after_ordinal INTEGER DEFAULT -1, page_size INTEGER DEFAULT 32)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
BEGIN
    PERFORM internal.require_service_role();
    PERFORM internal.explore_reaction_post(self_id, target_kind, target_id);
    RETURN internal.explore_reaction_page(self_id, target_kind, target_id, after_ordinal, page_size);
END;
$$;

CREATE FUNCTION public.get_explore_reaction_previews(self_id UUID, target_kind TEXT, target_ids UUID[])
RETURNS TABLE(target_id UUID, reactions JSONB, reactions_next_cursor INTEGER)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE item UUID; page JSONB;
BEGIN
    PERFORM internal.require_service_role();
    IF cardinality(target_ids) > 100 THEN RAISE EXCEPTION 'Too many targets' USING ERRCODE = '22023'; END IF;
    FOREACH item IN ARRAY target_ids LOOP
        BEGIN
            PERFORM internal.explore_reaction_post(self_id, target_kind, item);
            page := internal.explore_reaction_page(self_id, target_kind, item, -1, 12);
            target_id := item; reactions := page->'reactions';
            reactions_next_cursor := (page->>'reactions_next_cursor')::INTEGER;
            RETURN NEXT;
        EXCEPTION WHEN insufficient_privilege THEN
            -- An item may disappear between the catalog read and its bounded enrichment.
            CONTINUE;
        END;
    END LOOP;
END;
$$;

CREATE FUNCTION public.set_explore_reaction(self_id UUID, target_kind TEXT, target_id UUID,
    requested_emoji TEXT, selected BOOLEAN)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE resolved_post_id UUID; canonical TEXT; emoji_order INTEGER; aliases TEXT[]; page JSONB;
    reaction JSONB; likes INTEGER; liked BOOLEAN;
BEGIN
    PERFORM internal.require_service_role();
    IF selected IS NULL OR octet_length(requested_emoji) > 256 THEN
        RAISE EXCEPTION 'Invalid reaction' USING ERRCODE = '22023'; END IF;
    SELECT e.emoji, e.ordinal, e.aliases INTO canonical, emoji_order, aliases
        FROM internal.explore_emoji_catalog e WHERE requested_emoji = ANY(e.aliases);
    IF canonical IS NULL THEN RAISE EXCEPTION 'Choose one supported emoji' USING ERRCODE = '22023'; END IF;
    resolved_post_id := internal.explore_reaction_post(self_id, target_kind, target_id);
    -- Serialize all reactions on the post, including notification count recomputation.
    PERFORM 1 FROM public.explore_posts p WHERE p.id = resolved_post_id FOR UPDATE;
    PERFORM internal.explore_reaction_post(self_id, target_kind, target_id);
    IF target_kind = 'post' AND canonical = '❤️' THEN
        IF selected THEN
            INSERT INTO public.explore_post_likes(post_id,user_id) VALUES(resolved_post_id,self_id) ON CONFLICT DO NOTHING;
        ELSE
            DELETE FROM public.explore_post_likes r WHERE r.post_id = target_id AND r.user_id = self_id;
        END IF;
        SELECT p.like_count INTO likes FROM public.explore_posts p WHERE p.id = target_id;
        SELECT EXISTS(SELECT 1 FROM public.explore_post_likes r WHERE r.post_id = target_id AND r.user_id = self_id) INTO liked;
        reaction := jsonb_build_object('emoji',canonical,'count',likes,'viewer_has_reacted',liked,'order',emoji_order);
        RETURN jsonb_build_object('success',true,'target_id',target_id,'reaction',reaction,'like_count',likes,'viewer_has_liked',liked);
    ELSIF target_kind = 'post' THEN
        IF selected THEN
            INSERT INTO public.explore_post_reactions(post_id,user_id,emoji) VALUES(target_id,self_id,canonical) ON CONFLICT DO NOTHING;
        ELSE
            DELETE FROM public.explore_post_reactions r WHERE r.post_id = target_id AND r.user_id = self_id AND r.emoji = canonical;
        END IF;
    ELSE
        -- Existing recognized aliases count as the same reaction; a set-true retry never toggles.
        IF selected THEN
            IF NOT EXISTS(SELECT 1 FROM public.explore_comment_reactions r WHERE r.comment_id = target_id AND r.user_id = self_id AND r.emoji = ANY(aliases)) THEN
                INSERT INTO public.explore_comment_reactions(comment_id,user_id,emoji) VALUES(target_id,self_id,canonical) ON CONFLICT DO NOTHING;
            END IF;
        ELSE
            DELETE FROM public.explore_comment_reactions r WHERE r.comment_id = target_id AND r.user_id = self_id AND r.emoji = ANY(aliases);
        END IF;
    END IF;
    page := internal.explore_reaction_page(self_id, target_kind, target_id, emoji_order - 1, 1);
    reaction := page->'reactions'->0;
    IF reaction IS NULL OR reaction->>'emoji' <> canonical THEN
        reaction := jsonb_build_object('emoji',canonical,'count',0,'viewer_has_reacted',false,'order',emoji_order);
    END IF;
    RETURN jsonb_build_object('success',true,'target_id',target_id,'reaction',reaction);
END;
$$;
ALTER TABLE public.explore_post_notifications
    DROP CONSTRAINT IF EXISTS explore_post_notifications_comment_shape;

ALTER TABLE public.explore_post_notifications
    ADD CONSTRAINT explore_post_notifications_comment_shape CHECK (
        (
            type = 'comment'
            AND post_id IS NOT NULL
            AND community_request_id IS NULL
            AND comment_id IS NOT NULL
            AND reaction_emoji IS NULL
            AND triggering_user_id IS NOT NULL
            AND COALESCE(ARRAY_LENGTH(recent_actor_ids, 1), 0) = 0
            AND action_count = 1
        )
        OR (
            type = 'comment_reply'
            AND post_id IS NOT NULL
            AND community_request_id IS NULL
            AND comment_id IS NOT NULL
            AND reaction_emoji IS NULL
            AND triggering_user_id IS NOT NULL
            AND COALESCE(ARRAY_LENGTH(recent_actor_ids, 1), 0) = 0
            AND action_count = 1
        )
        OR (
            type = 'comment_mention'
            AND post_id IS NOT NULL
            AND community_request_id IS NULL
            AND comment_id IS NOT NULL
            AND reaction_emoji IS NULL
            AND triggering_user_id IS NOT NULL
            AND COALESCE(ARRAY_LENGTH(recent_actor_ids, 1), 0) = 0
            AND action_count = 1
        )
        OR (
            type = 'like_aggregated'
            AND post_id IS NOT NULL
            AND community_request_id IS NULL
            AND comment_id IS NULL
            AND reaction_emoji IS NULL
            AND COALESCE(ARRAY_LENGTH(recent_actor_ids, 1), 0) <= 3
        )
        OR (
            type IN ('comment_reaction', 'post_reaction')
            AND post_id IS NOT NULL
            AND community_request_id IS NULL
            AND ((type = 'comment_reaction' AND comment_id IS NOT NULL) OR (type = 'post_reaction' AND comment_id IS NULL))
            AND reaction_emoji IS NOT NULL
            AND triggering_user_id IS NOT NULL
            AND COALESCE(ARRAY_LENGTH(recent_actor_ids, 1), 0) <= 3
            AND action_count >= 1
        )
        OR (
            type = 'follow'
            AND post_id IS NULL
            AND community_request_id IS NULL
            AND comment_id IS NULL
            AND reaction_emoji IS NULL
            AND triggering_user_id IS NOT NULL
            AND COALESCE(ARRAY_LENGTH(recent_actor_ids, 1), 0) = 0
            AND action_count = 1
        )
        OR (
            type = 'community_identification_added'
            AND post_id IS NOT NULL
            AND community_request_id IS NOT NULL
            AND comment_id IS NULL
            AND reaction_emoji IS NULL
            AND triggering_user_id IS NOT NULL
            AND COALESCE(ARRAY_LENGTH(recent_actor_ids, 1), 0) <= 3
            AND action_count >= 1
        )
        OR (
            type IN (
                'community_request_resolved',
                'community_identification_helped'
            )
            AND post_id IS NOT NULL
            AND community_request_id IS NOT NULL
            AND comment_id IS NULL
            AND reaction_emoji IS NULL
            AND triggering_user_id IS NULL
            AND COALESCE(ARRAY_LENGTH(recent_actor_ids, 1), 0) = 0
            AND action_count = 1
        )
        OR (
            type IN ('media_missing', 'media_restored')
            AND post_id IS NOT NULL
            AND community_request_id IS NULL
            AND comment_id IS NULL
            AND reaction_emoji IS NULL
            AND triggering_user_id IS NULL
            AND COALESCE(ARRAY_LENGTH(recent_actor_ids, 1), 0) = 0
            AND action_count = 1
        )
    );

CREATE UNIQUE INDEX explore_notifications_post_reaction_unique
    ON public.explore_post_notifications(user_id, post_id, reaction_emoji) WHERE type = 'post_reaction';

CREATE FUNCTION internal.sync_explore_post_reaction_notification()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE target_post UUID; target_emoji TEXT; recipient UUID; actors UUID[]; total INTEGER;
BEGIN
    target_post := CASE WHEN TG_OP = 'DELETE' THEN OLD.post_id ELSE NEW.post_id END;
    target_emoji := CASE WHEN TG_OP = 'DELETE' THEN OLD.emoji ELSE NEW.emoji END;
    SELECT p.user_id INTO recipient FROM public.explore_posts p WHERE p.id = target_post FOR UPDATE;
    IF recipient = (CASE WHEN TG_OP = 'DELETE' THEN OLD.user_id ELSE NEW.user_id END) THEN
        RETURN NULL;
    END IF;
    SELECT count(*)::INTEGER INTO total FROM public.explore_post_reactions r
      JOIN public.users u ON u.id = r.user_id AND NOT u.is_shadowbanned
      WHERE r.post_id = target_post AND r.emoji = target_emoji AND r.user_id <> recipient
        AND NOT EXISTS(SELECT 1 FROM public.user_blocks b WHERE
          (b.blocker_id=recipient AND b.blocked_id=r.user_id) OR (b.blocked_id=recipient AND b.blocker_id=r.user_id));
    IF recipient IS NULL OR total = 0 THEN
        DELETE FROM public.explore_post_notifications n WHERE n.post_id = target_post
            AND n.type = 'post_reaction' AND n.reaction_emoji = target_emoji;
        RETURN NULL;
    END IF;
    actors := ARRAY(SELECT r.user_id FROM public.explore_post_reactions r
        JOIN public.users u ON u.id = r.user_id AND NOT u.is_shadowbanned
        WHERE r.post_id = target_post AND r.emoji = target_emoji AND r.user_id <> recipient
          AND NOT EXISTS(SELECT 1 FROM public.user_blocks b WHERE
            (b.blocker_id=recipient AND b.blocked_id=r.user_id) OR (b.blocked_id=recipient AND b.blocker_id=r.user_id))
        ORDER BY r.created_at DESC, r.user_id LIMIT 3);
    INSERT INTO public.explore_post_notifications(user_id,post_id,type,reaction_emoji,triggering_user_id,recent_actor_ids,action_count,is_read)
    VALUES(recipient,target_post,'post_reaction',target_emoji,actors[1],actors,total,false)
    ON CONFLICT(user_id,post_id,reaction_emoji) WHERE type = 'post_reaction'
    DO UPDATE SET triggering_user_id=EXCLUDED.triggering_user_id, recent_actor_ids=EXCLUDED.recent_actor_ids,
      action_count=EXCLUDED.action_count,
      is_read=CASE WHEN TG_OP = 'INSERT' THEN false ELSE explore_post_notifications.is_read END,
      updated_at=CASE WHEN TG_OP = 'INSERT' THEN now() ELSE explore_post_notifications.updated_at END;
    RETURN NULL;
END;
$$;
CREATE TRIGGER explore_post_reaction_notification AFTER INSERT OR DELETE ON public.explore_post_reactions
    FOR EACH ROW EXECUTE FUNCTION internal.sync_explore_post_reaction_notification();

-- Recompute visible actor counts at read time; stored aggregates are not an authorization boundary.
CREATE FUNCTION internal.explore_visible_post_reactors(self_id UUID, target_post_id UUID, target_emoji TEXT)
RETURNS TABLE(user_id UUID, created_at TIMESTAMPTZ) LANGUAGE sql STABLE SET search_path = '' AS $$
    SELECT r.user_id, r.created_at FROM public.explore_post_reactions r
    JOIN public.users u ON u.id=r.user_id AND NOT u.is_shadowbanned
    JOIN public.explore_posts p ON p.id=r.post_id
    WHERE r.post_id=target_post_id AND r.emoji=target_emoji AND r.user_id<>p.user_id
      AND NOT EXISTS(SELECT 1 FROM public.user_blocks b WHERE
        (b.blocker_id=self_id AND b.blocked_id=r.user_id) OR (b.blocked_id=self_id AND b.blocker_id=r.user_id));
$$;
REVOKE ALL ON FUNCTION internal.explore_visible_post_reactors(UUID,UUID,TEXT) FROM PUBLIC,anon,authenticated,service_role;

