CREATE FUNCTION public.get_unread_explore_notification_count_with_reactions(self_id UUID)
RETURNS INTEGER LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE result INTEGER;
BEGIN
    PERFORM internal.require_service_role();
    SELECT count(*)::INTEGER INTO result FROM public.get_explore_notifications_with_reactions(self_id, 1000000, NULL, NULL) n WHERE NOT n.is_read;
    RETURN result;
END;
$$;
CREATE FUNCTION public.mark_explore_notifications_read_with_reactions(self_id UUID)
RETURNS INTEGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE legacy_count INTEGER; reaction_count INTEGER;
BEGIN
    PERFORM internal.require_service_role();
    legacy_count := public.mark_explore_notifications_read(self_id);
    UPDATE public.explore_post_notifications SET is_read = true
    WHERE user_id = self_id AND type = 'post_reaction' AND NOT is_read
      AND id IN (SELECT notification_id FROM public.get_explore_notifications_with_reactions(self_id, 1000000, NULL, NULL));
    GET DIAGNOSTICS reaction_count = ROW_COUNT;
    RETURN legacy_count + reaction_count;
END;
$$;

CREATE FUNCTION public.toggle_explore_comment_reaction(self_id UUID, target_id UUID, requested_emoji TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE resolved_post UUID; selected BOOLEAN; aliases TEXT[];
BEGIN
    PERFORM internal.require_service_role();
    resolved_post := internal.explore_reaction_post(self_id,'comment',target_id);
    PERFORM 1 FROM public.explore_posts p WHERE p.id=resolved_post FOR UPDATE;
    SELECT e.aliases INTO aliases FROM internal.explore_emoji_catalog e WHERE requested_emoji=ANY(e.aliases);
    SELECT NOT EXISTS(SELECT 1 FROM public.explore_comment_reactions r
        WHERE r.comment_id=target_id AND r.user_id=self_id AND r.emoji=ANY(aliases)) INTO selected;
    RETURN public.set_explore_reaction(self_id,'comment',target_id,requested_emoji,selected);
END;
$$;
REVOKE ALL ON FUNCTION public.toggle_explore_comment_reaction(UUID,UUID,TEXT) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.toggle_explore_comment_reaction(UUID,UUID,TEXT) TO service_role;
INSERT INTO internal.privileged_routine_grants(role_name,routine_signature,purpose)
VALUES('service_role','public.toggle_explore_comment_reaction(uuid,uuid,text)','Legacy comment reaction toggle through guarded transactional mutation');

