-- Keep account upgrades atomic when both identities reacted with the same emoji.
INSERT INTO internal.ghost_profile_merge_reference_policies(
    source_schema,source_table,source_column,referenced_schema,referenced_table,referenced_column,
    strategy,execution_order,handler_key,purpose)
VALUES('public','explore_post_reactions','user_id','public','users','id','reparent',500,NULL,
    'Post reactions follow the permanent profile after duplicate and self-reaction resolution.');
DO $migration$
DECLARE original TEXT; patched TEXT; marker TEXT := '-- Collapse duplicate reactions and likes before the generic FK reparent.';
BEGIN
    original := pg_catalog.pg_get_functiondef('internal.merge_ghost_social_conflicts(uuid,uuid)'::regprocedure);
    IF strpos(original, marker) = 0 THEN RAISE EXCEPTION 'Ghost social merge source drift'; END IF;
    patched := replace(original, marker, $patch$
    DELETE FROM public.explore_post_reactions ghost
    USING public.explore_post_reactions target
    WHERE ghost.user_id=p_ghost_user_id AND target.user_id=p_target_user_id
      AND ghost.post_id=target.post_id AND ghost.emoji=target.emoji;
    DELETE FROM public.explore_post_reactions r USING public.explore_posts p
    WHERE r.post_id=p.id AND (r.user_id=p_ghost_user_id OR p.user_id=p_ghost_user_id)
      AND (CASE WHEN r.user_id=p_ghost_user_id THEN p_target_user_id ELSE r.user_id END)
        = (CASE WHEN p.user_id=p_ghost_user_id THEN p_target_user_id ELSE p.user_id END);
    $patch$ || marker);
    EXECUTE patched;
END;
$migration$;
SELECT internal.assert_ghost_profile_merge_reference_policy_coverage();

